alter table public.saving_goals add column lifecycle_status text not null default 'ACTIVE' check(lifecycle_status in('ACTIVE','PAUSED','FUNDED','CANCELLED','ARCHIVED'));
create function public.set_saving_goal_paused(p_goal_id uuid,p_paused boolean,p_expected_version integer) returns public.saving_goals language plpgsql security definer set search_path='' as $$ declare u uuid:=auth.uid(); g public.saving_goals; begin if u is null then raise exception 'AUTH_REQUIRED' using errcode='P0001'; end if; select * into g from public.saving_goals where id=p_goal_id and user_id=u and deleted_at is null for update; if not found then raise exception 'GOAL_NOT_FOUND' using errcode='P0001'; end if; if g.version<>p_expected_version then raise exception 'VERSION_CONFLICT' using errcode='P0001'; end if; if g.saved_amount>=g.target_amount and p_paused then raise exception 'GOAL_ALREADY_FUNDED' using errcode='P0001'; end if; update public.saving_goals set lifecycle_status=case when p_paused then 'PAUSED' else 'ACTIVE' end where id=g.id returning * into g; return g; end $$;
create function public.reallocate_saving_goal(p_source_goal_id uuid,p_destination_goal_id uuid,p_amount bigint,p_source_version integer,p_destination_version integer,p_operation_key text) returns uuid language plpgsql security definer set search_path='' as $$ declare u uuid:=auth.uid(); s public.saving_goals; d public.saving_goals; sl public.saving_virtual_locks; dl public.saving_virtual_locks; m uuid; begin if u is null then raise exception 'AUTH_REQUIRED' using errcode='P0001'; end if; if p_source_goal_id=p_destination_goal_id or p_amount<1 then raise exception 'INVALID_REALLOCATION' using errcode='P0001'; end if; perform 1 from public.saving_goals where id in(p_source_goal_id,p_destination_goal_id) and user_id=u and deleted_at is null order by id for update; select * into s from public.saving_goals where id=p_source_goal_id and user_id=u and deleted_at is null; select * into d from public.saving_goals where id=p_destination_goal_id and user_id=u and deleted_at is null; if s.id is null or d.id is null then raise exception 'GOAL_NOT_FOUND' using errcode='P0001'; end if; if s.version<>p_source_version or d.version<>p_destination_version then raise exception 'VERSION_CONFLICT' using errcode='P0001'; end if; if s.saved_amount<p_amount or d.saved_amount+p_amount>d.target_amount then raise exception 'INVALID_GOAL_BALANCE' using errcode='P0001'; end if; if s.funding_mode<>d.funding_mode or s.funding_mode='VIRTUAL_LOCK' and s.source_account_id<>d.source_account_id or s.funding_mode='SEPARATE_ACCOUNT' and s.savings_account_id<>d.savings_account_id then raise exception 'INCOMPATIBLE_FUNDING_LOCATION' using errcode='P0001'; end if; if s.funding_mode='VIRTUAL_LOCK' then select * into sl from public.saving_virtual_locks where goal_id=s.id for update; select * into dl from public.saving_virtual_locks where goal_id=d.id for update; if sl.id is null or sl.locked_amount<p_amount then raise exception 'INSUFFICIENT_LOCK' using errcode='P0001'; end if; if sl.locked_amount=p_amount then delete from public.saving_virtual_locks where id=sl.id; else update public.saving_virtual_locks set locked_amount=locked_amount-p_amount where id=sl.id; end if; if dl.id is null then insert into public.saving_virtual_locks(user_id,goal_id,account_id,locked_amount) values(u,d.id,d.source_account_id,p_amount); else update public.saving_virtual_locks set locked_amount=locked_amount+p_amount where id=dl.id; end if; end if; insert into public.saving_goal_mutations(user_id,goal_id,account_id,operation_key,kind,amount,note) values(u,s.id,s.source_account_id,p_operation_key||'-out','WITHDRAWAL',p_amount,'Realokasi ke '||d.name); insert into public.saving_goal_mutations(user_id,goal_id,account_id,operation_key,kind,amount,note) values(u,d.id,d.source_account_id,p_operation_key||'-in','DEPOSIT',p_amount,'Realokasi dari '||s.name) returning id into m; update public.saving_goals set saved_amount=saved_amount-p_amount,lifecycle_status='ACTIVE' where id=s.id; update public.saving_goals set saved_amount=saved_amount+p_amount,lifecycle_status=case when saved_amount+p_amount>=target_amount then 'FUNDED' else lifecycle_status end where id=d.id; return m; end $$;
create function public.prevent_funded_goal_deletion() returns trigger language plpgsql set search_path='' as $$ begin if new.deleted_at is not null and old.deleted_at is null and old.saved_amount>0 then raise exception 'FUNDED_GOAL_REQUIRES_DISPOSITION' using errcode='P0001'; end if; return new; end $$;
create trigger saving_goals_prevent_funded_delete before update of deleted_at on public.saving_goals for each row execute function public.prevent_funded_goal_deletion();
revoke execute on function public.set_saving_goal_paused(uuid,boolean,integer),public.reallocate_saving_goal(uuid,uuid,bigint,integer,integer,text) from public,anon;
grant execute on function public.set_saving_goal_paused(uuid,boolean,integer),public.reallocate_saving_goal(uuid,uuid,bigint,integer,integer,text) to authenticated;
revoke execute on function public.prevent_funded_goal_deletion() from public,anon,authenticated;
